use std::process::{Command, Output};
use std::collections::HashMap;

/// Represents the result of an executed system command.
#[derive(Debug)]
pub struct CommandResult {
    pub stdout: String,
    pub stderr: String,
    pub exit_code: i32,
    pub success: bool,
}

/// Executes an arbitrary shell command string via `sh -c`.
/// Returns a `CommandResult` with stdout, stderr, exit code, and success flag.
pub fn run_shell_command(cmd: &str) -> Result<CommandResult, String> {
    let output: Output = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()
        .map_err(|e| format!("Failed to spawn command: {}", e))?;

    Ok(CommandResult {
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        exit_code: output.status.code().unwrap_or(-1),
        success: output.status.success(),
    })
}

/// Executes a command with explicit arguments (avoids shell injection).
/// `program` is the binary; `args` is the list of arguments.
pub fn run_command(program: &str, args: &[&str]) -> Result<CommandResult, String> {
    let output: Output = Command::new(program)
        .args(args)
        .output()
        .map_err(|e| format!("Failed to spawn '{}': {}", program, e))?;

    Ok(CommandResult {
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        exit_code: output.status.code().unwrap_or(-1),
        success: output.status.success(),
    })
}

